import{_ as a,o as e,c as l,a5 as r}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"行动篇：九十天，把生活交还给自己","description":"用目标、基线、输出、反馈、作品和身体边界，建立一套可复测、可恢复的九十天行动系统。","frontmatter":{"title":"行动篇：九十天，把生活交还给自己","description":"用目标、基线、输出、反馈、作品和身体边界，建立一套可复测、可恢复的九十天行动系统。","updated":"2026-11-23T00:00:00.000Z"},"headers":[],"relativePath":"threads/part-5/90-day-plan.md","filePath":"threads/part-5/90-day-plan.md","lastUpdated":1795392000000}'),i={name:"threads/part-5/90-day-plan.md"};function o(d,t,n,h,p,s){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="行动篇-九十天-把生活交还给自己" tabindex="-1">行动篇：九十天，把生活交还给自己 <a class="header-anchor" href="#行动篇-九十天-把生活交还给自己" aria-label="Permalink to &quot;行动篇：九十天，把生活交还给自己&quot;">​</a></h1><p>很多人读完一篇方法论，会立刻收藏下一篇方法论。收藏的瞬间很像开始，实际上只是把开始推迟到了一个更舒服的地方。</p><p>真正的进阶不靠一阵兴奋，而靠一段可以被检验的时间。这里给出一个九十天计划：不要求你脱胎换骨，只要求你在三个月后拿出一组证据，证明自己比今天更能理解、更能表达，也更能把事情做完。如果你还没有找到适合自己的日常节奏，可以先读<a href="./../part-4/rhythm-and-compounding">节律篇：让小事穿过时间</a>，再把一个能在中断后回来的动作交给这九十天。</p><h2 id="先定义-变好" tabindex="-1">先定义“变好” <a class="header-anchor" href="#先定义-变好" aria-label="Permalink to &quot;先定义“变好”&quot;">​</a></h2><p>不要写“我要提升英语”“我要学会 AI”“我要变自律”。这些愿望没有错，但无法指导今天的选择。</p><p>请把目标改写成下面的句式：</p><blockquote><p>在九十天内，我要在 <strong>某个真实场景</strong> 中完成 <strong>一个可交付成果</strong>，并用 <strong>三项证据</strong> 判断是否达成。</p></blockquote><p>例如：</p><ul><li>在九十天内，我要用英语完成一次 10 分钟的产品演示；证据是录音、逐字稿和一位听众的反馈。</li><li>在九十天内，我要做出一个自动整理表格的小工具；证据是可运行代码、使用说明和一次真实使用记录。</li><li>在九十天内，我要写完 12 篇关于行业观察的短文；证据是发布链接、读者反馈和一份自我复盘。</li></ul><p>目标越接近真实生活，越不容易被“准备得还不够”绑架。</p><p>可以先复制<a href="./../../templates/90-day-cycle">九十日行动总表</a>，再把下面的阶段和每周问题填进去。总表不是新的打卡系统，而是把已有证据放在同一条时间线上；用<a href="./../../templates/evidence-chain">证据链模板</a>解释四个时间点，用<a href="./../../templates/rhythm-ledger">节律账本</a>维护每周的可回归节奏。</p><h2 id="_1-用一页纸盘点起点" tabindex="-1">1. 用一页纸盘点起点 <a class="header-anchor" href="#_1-用一页纸盘点起点" aria-label="Permalink to &quot;1. 用一页纸盘点起点&quot;">​</a></h2><p>在第一天，花 30 分钟写下四栏内容：</p><table tabindex="0"><thead><tr><th>栏目</th><th>要回答的问题</th></tr></thead><tbody><tr><td>现状</td><td>我现在能独立完成什么？卡在哪里？</td></tr><tr><td>场景</td><td>三个月后我要在哪个场合使用这项能力？</td></tr><tr><td>资源</td><td>每周稳定可用的时间、材料、工具和同伴是什么？</td></tr><tr><td>代价</td><td>哪些事情必须少做，才能给目标让出位置？</td></tr></tbody></table><p>最后一栏最重要。没有代价的计划，只是一张愿望清单。你不可能同时把所有兴趣都推进到前台；选择一个主线，并不等于背叛其他可能，而是暂时给其中一件事足够的光。</p><h2 id="四项能力如何合流" tabindex="-1">四项能力如何合流 <a class="header-anchor" href="#四项能力如何合流" aria-label="Permalink to &quot;四项能力如何合流&quot;">​</a></h2><p>不必每周平均练习听、读、说、写。选择一项最接近真实目标的主能力，再用另一项能力提供输入或反馈：</p><table tabindex="0"><thead><tr><th>环节</th><th>作用</th><th>可留下的证据</th></tr></thead><tbody><tr><td>听力/阅读</td><td>获取材料、理解问题和证据</td><td><a href="./../../templates/listening-audit">听力证据卡</a>或<a href="./../../templates/reading-evidence">阅读证据卡</a></td></tr><tr><td>口语/写作</td><td>把理解变成说明、决定或作品</td><td><a href="./../../templates/speaking-evidence">口语证据卡</a>或<a href="./../../templates/writing-evidence">写作证据卡</a></td></tr><tr><td>反馈/复盘</td><td>找出最大障碍并决定下一变量</td><td><a href="./../../templates/weekly-review">每周复盘</a>与<a href="./../../templates/learning-state">学习状态</a></td></tr><tr><td>交付/迁移</td><td>在新听众、主题或真实场景中检验</td><td>作品链接、用户反馈或平行任务</td></tr></tbody></table><p>如果四项活动都没有指向同一个任务，它们很容易重新变成互不相干的打卡。每周至少保留一项输入、一项输出和一次迁移，其余时间服务于主线。</p><h2 id="_2-九十天分成三个阶段" tabindex="-1">2. 九十天分成三个阶段 <a class="header-anchor" href="#_2-九十天分成三个阶段" aria-label="Permalink to &quot;2. 九十天分成三个阶段&quot;">​</a></h2><h3 id="第一阶段-校准-第-1—14-天" tabindex="-1">第一阶段：校准（第 1—14 天） <a class="header-anchor" href="#第一阶段-校准-第-1—14-天" aria-label="Permalink to &quot;第一阶段：校准（第 1—14 天）&quot;">​</a></h3><p>这一阶段不追求速度，只追求看清。</p><ul><li>做一次基线测试：录一段英语自我介绍，或完成一个与你目标相关的最小任务；</li><li>找出最常出现的三个错误，不要一次修理三十个；</li><li>建立固定时段，哪怕每天只有 25 分钟；</li><li>清理材料，只保留一个主教材、一个练习场景和一个记录地方。</li></ul><p>两周后，你应该能回答：“我究竟在练什么？我的问题是什么？我下一次要重复哪一个动作？”如果还回答不了，先不要加码。</p><h3 id="第二阶段-堆叠-第-15—56-天" tabindex="-1">第二阶段：堆叠（第 15—56 天） <a class="header-anchor" href="#第二阶段-堆叠-第-15—56-天" aria-label="Permalink to &quot;第二阶段：堆叠（第 15—56 天）&quot;">​</a></h3><p>把同一个动作重复到足够熟，再逐步增加难度。推荐每周保持四类活动：</p><ol><li><strong>输入</strong>：两到三次精听、精读或示范拆解；</li><li><strong>输出</strong>：两次口头复述、写作、编码或公开表达；</li><li><strong>反馈</strong>：一次针对作品的具体修改；</li><li><strong>复盘</strong>：一次 20 分钟的周记录，决定下周删掉什么、保留什么。</li></ol><p>AI 可以在这里做教练、陪练、审稿人和测试员，但不要让它替你完成全部输出。先交出自己的粗糙版本，再让工具指出最值得修的地方；你亲手修改的那一遍，才是能力真正发生的地方。</p><h3 id="第三阶段-交付-第-57—90-天" tabindex="-1">第三阶段：交付（第 57—90 天） <a class="header-anchor" href="#第三阶段-交付-第-57—90-天" aria-label="Permalink to &quot;第三阶段：交付（第 57—90 天）&quot;">​</a></h3><p>从第八周起，停止无限扩展课程。把已经学过的内容集中到一个作品中：一场演讲、一篇长文、一个工具、一份报告、一次面试模拟，或者一场真实的沟通。</p><p>交付前至少做三轮：</p><ul><li><strong>独立版</strong>：不看答案，按真实条件完成；</li><li><strong>修订版</strong>：根据反馈，只改最影响理解和结果的问题；</li><li><strong>公开版</strong>：交给真实的人使用、阅读或评价。</li></ul><p>作品不需要漂亮到可以获奖，但要足够真实，能让你知道下一阶段该往哪里走。</p><h2 id="_3-一周只保留一个主问题" tabindex="-1">3. 一周只保留一个主问题 <a class="header-anchor" href="#_3-一周只保留一个主问题" aria-label="Permalink to &quot;3. 一周只保留一个主问题&quot;">​</a></h2><p>每周开始时写一句问题，而不是列十项任务：</p><blockquote><p>本周我要弄明白：我能否在不查稿的情况下，用英语解释我的工作？</p></blockquote><p>围绕这个问题安排练习：</p><ul><li>周一：收集三个自然表达，听懂它们在真实语境里的用法；</li><li>周二：自己写一版 90 秒回答；</li><li>周三：录音并标出卡顿、重复和听不清的地方；</li><li>周四：请 AI 或同伴只指出三个高价值问题；</li><li>周五：重录第二版，加入一个追问；</li><li>周末：把录音、修改点和下一周问题放进同一个文件。</li></ul><p>这样做的好处，是你能在周末看到一条完整的证据链，而不是一堆互不相干的打卡截图。把首版、即时表现、延迟保持和迁移放进<a href="./../../templates/evidence-chain">证据链模板</a>，再把决定写回周期表。</p><h2 id="_4-每天的最小闭环" tabindex="-1">4. 每天的最小闭环 <a class="header-anchor" href="#_4-每天的最小闭环" aria-label="Permalink to &quot;4. 每天的最小闭环&quot;">​</a></h2><p>当生活混乱、时间被切碎时，使用 45 分钟版本：</p><ol><li><strong>5 分钟回忆</strong>：不看资料，写下昨天记得的三点；</li><li><strong>15 分钟输入</strong>：只处理一小段材料，标出真正影响理解的难点；</li><li><strong>15 分钟输出</strong>：说、写、做或演示一个可见结果；</li><li><strong>5 分钟反馈</strong>：记录一个错误和一个可以复用的表达；</li><li><strong>5 分钟安排</strong>：写下明天打开文件后要做的第一步。</li></ol><p>如果只有 10 分钟，就保留“回忆—输出—记录”三步。节奏可以缩短，闭环不要消失。</p><h2 id="_5-失败时不要重启人生-只重启下一步" tabindex="-1">5. 失败时不要重启人生，只重启下一步 <a class="header-anchor" href="#_5-失败时不要重启人生-只重启下一步" aria-label="Permalink to &quot;5. 失败时不要重启人生，只重启下一步&quot;">​</a></h2><p>计划一定会中断。生病、加班、争吵、失眠、突发的账单，都会把理想日程打碎。中断本身不是失败，把一次中断解释成“我果然不行”，才会让它扩大。</p><p>请使用这个恢复协议：</p><ol><li>写下事实：我连续几天没有练习，除此之外不做人格判断；</li><li>找出阻力：时间不够、任务太难、情绪低落，还是环境不支持；</li><li>把任务缩小到原来的三分之一；</li><li>在 24 小时内完成一次极小的输出；</li><li>不补作业，不熬夜还债，直接回到今天。</li></ol><p>长期主义不是永远不掉队，而是掉队之后不再用羞耻惩罚自己。</p><h2 id="_6-给自己一张诚实的记分卡" tabindex="-1">6. 给自己一张诚实的记分卡 <a class="header-anchor" href="#_6-给自己一张诚实的记分卡" aria-label="Permalink to &quot;6. 给自己一张诚实的记分卡&quot;">​</a></h2><p>每周日只记录以下五项，采用“完成 / 未完成”，不要用模糊的“感觉还行”：</p><ul><li>我是否完成了至少两次主动输出？</li><li>我是否得到过一次来自他人或 AI 的具体反馈？</li><li>我是否把一个错误改成了下一次的练习？</li><li>我是否留下了一个可以展示或复用的成果？</li><li>我是否为睡眠、运动和关系保留了基本空间？</li></ul><p>最后一项不是额外奖励，而是基础设施。身体不是承载目标的容器，身体本身就是人生的一部分。任何必须靠长期透支才能维持的计划，都应该被重新设计。</p><h2 id="_7-九十天之后-留下三样东西" tabindex="-1">7. 九十天之后，留下三样东西 <a class="header-anchor" href="#_7-九十天之后-留下三样东西" aria-label="Permalink to &quot;7. 九十天之后，留下三样东西&quot;">​</a></h2><p>计划结束时，不要只问“我坚持了多少天”。请留下：</p><ol><li><strong>一个作品</strong>：证明你做过，而不是只学过；</li><li><strong>一份错误地图</strong>：列出仍然反复出现的问题，以及下一阶段的优先级；</li><li><strong>一条可持续节奏</strong>：即使忙碌，也能保留的最小训练单元。</li></ol><p>如果这三样都在，九十天就没有白过。你得到的不是一套漂亮的自律人设，而是一种更可靠的自我信任：我知道自己怎样开始，怎样修正，怎样把事情做完。</p><h2 id="结语-把进阶还给日子" tabindex="-1">结语：把进阶还给日子 <a class="header-anchor" href="#结语-把进阶还给日子" aria-label="Permalink to &quot;结语：把进阶还给日子&quot;">​</a></h2><p>我越来越不相信“彻底改变”这句话。它听起来有力，却常常把人带到更大的失望里。真正可贵的变化，通常没有戏剧性的配乐：一个人按时起床，打开昨天留下的文件；在会议里说出准备过的第一句英语；把一篇文章改到自己愿意署名；在很想逃走的时候，先把事实看清楚。</p><p>愿你用九十天换来的，不只是某项技能，而是对生活重新拥有一点触感。愿你知道自己在往哪里走，也允许道路暂时没有掌声。</p>',59)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
